Build a complete website for the following brief with layout: split_hero.

<content_brief>
  <business_name>Apex Advisory Partners</business_name>
  <tagline>Modern Fractional CFO and Tax Strategy for Scale</tagline>
  <business_type>accounting</business_type>
  <layout_archetype>split_hero</layout_archetype>
  <layout_guidelines>50/50 split-screen hero layout with prominent brand typography and CTA on the left, paired with an interactive visual sandbox/widget on the right.</layout_guidelines>
  <motion_guidelines>Split Hero Motion: Implement coordinated asymmetric entrance with offset delays (left brand text at 0ms, right interactive visual widget at 160ms). Mandatory reduced-motion fallback: @media (prefers-reduced-motion: reduce) { .split-hero__left, .split-hero__right { opacity: 1 !important; transform: none !important; animation: none !important; } }</motion_guidelines>
  <primary_color>#0a1322</primary_color>
  <accent_color>#38bdf8</accent_color>
  <font_heading>Plus Jakarta Sans</font_heading>
  <font_body>Inter</font_body>
  <sections>header, hero, services, footer</sections>
  <item name="Fractional CFO & Runway Modeling" tag="Strategic" description="Multi-scenario cash burn forecasting, capital allocation roadmaps, and investor board deck preparation." />
  <item name="R&D Tax Credit Optimization" tag="Tax" description="Maximizing federal and state research incentives to reclaim up to $250k annually against payroll taxes." />
  <item name="Automated Cloud Accounting" tag="Operations" description="Full QuickBooks and NetSuite migration with automated Stripe reconciliation and multi-currency ledgers." />
  <item name="SOC 1 & GAAP Audit Prep" tag="Compliance" description="Rigorous balance sheet substantiation, revenue recognition (ASC 606), and external auditor management." />
  <contact>
    <address>111 W Washington St, Suite 1800, Chicago, IL 60602</address>
    <phone>+1 (312) 555-0188</phone>
    <email>partners@apexadvisorycfo.com</email>
    <hours>Mon–Fri: 8:30am–5:30pm CST</hours>
  </contact>
</content_brief>

You will build the site ONE SECTION AT A TIME. Start with the first section now.

FIRST SECTION REQUIRED: Write the Header section: a sticky navigation bar with the business name/logo on the left, navigation links (Home, Advisory Capabilities, Contact) on the right, plus 'Request Audit' CTA button. Files: src/components/Header.tsx + src/components/Header.css

Previous assistant implementation (context only):
<tool_call name="write_site">
<file path="src/components/Header.tsx">
import React, { useState, useEffect } from 'react';
import './Header.css';

export function Header() {
  const [scrolled, setScrolled] = useState(false);
  const [menuOpen, setMenuOpen] = useState(false);

  useEffect(() => {
    const onScroll = () => setScrolled(window.scrollY > 15);
    window.addEventListener('scroll', onScroll, { passive: true });
    return () => window.removeEventListener('scroll', onScroll);
  }, []);

  return (
    <header className={`aa-header${scrolled ? ' aa-header--scrolled' : ''}`} role="banner">
      <div className="aa-header__inner">
        <a href="#" className="aa-header__logo" aria-label="Apex Advisory Partners Home">
          Apex Advisory Partners
        </a>

        <nav className="aa-header__nav" aria-label="Main Navigation">
          <a href="#hero" className="aa-header__link">Home</a>
          <a href="#services" className="aa-header__link">Advisory Capabilities</a>
          <a href="#footer" className="aa-header__link">Contact</a>
        </nav>

        <div className="aa-header__actions">
          <a href="mailto:partners@apexadvisorycfo.com" className="aa-header__cta">
            Request Audit
          </a>
          <button
            type="button"
            className="aa-header__toggle"
            aria-label="Toggle navigation menu"
            aria-expanded={menuOpen}
            onClick={() => setMenuOpen(!menuOpen)}
          >
            <span className="aa-header__bar" />
            <span className="aa-header__bar" />
            <span className="aa-header__bar" />
          </button>
        </div>
      </div>

      {menuOpen && (
        <div className="aa-header__mobile-menu">
          <a href="#hero" onClick={() => setMenuOpen(false)}>Home</a>
          <a href="#services" onClick={() => setMenuOpen(false)}>Advisory Capabilities</a>
          <a href="#footer" onClick={() => setMenuOpen(false)}>Contact</a>
        </div>
      )}
    </header>
  );
}

</file>
<file path="src/components/Header.css">
.aa-header {
  position: sticky;
  top: 0;
  z-index: 100;
  width: 100%;
  background: rgba(10, 19, 34, 0.92);
  backdrop-filter: blur(12px);
  border-bottom: 1px solid rgba(255, 255, 255, 0.08);
  transition: all 0.3s cubic-bezier(0.16, 1, 0.3, 1);
}

.aa-header--scrolled {
  box-shadow: 0 4px 24px rgba(0, 0, 0, 0.4);
  border-bottom-color: #38bdf8;
}

.aa-header__inner {
  max-width: 1240px;
  margin: 0 auto;
  padding: 0 2rem;
  height: 74px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1.5rem;
}

.aa-header__logo {
  font-family: 'Plus Jakarta Sans', sans-serif;
  font-size: 1.35rem;
  font-weight: 700;
  color: #fafafa;
  text-decoration: none;
  letter-spacing: -0.01em;
}

.aa-header__nav {
  display: flex;
  gap: 2rem;
  align-items: center;
}

.aa-header__link {
  color: #a1a1aa;
  text-decoration: none;
  font-size: 0.92rem;
  font-weight: 500;
  transition: color 0.2s ease;
}

.aa-header__link:hover {
  color: #38bdf8;
}

.aa-header__actions {
  display: flex;
  align-items: center;
  gap: 1rem;
}

.aa-header__cta {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 0.6rem 1.4rem;
  background: #38bdf8;
  color: #0c0d12;
  font-size: 0.88rem;
  font-weight: 700;
  text-decoration: none;
  border-radius: 6px;
  transition: all 0.2s ease;
}

.aa-header__cta:hover {
  background: #0284c7;
  transform: translateY(-1px);
  box-shadow: 0 4px 14px rgba(56, 189, 248, 0.35);
}

.aa-header__toggle {
  display: none;
  background: transparent;
  border: none;
  cursor: pointer;
  padding: 6px;
  flex-direction: column;
  gap: 5px;
}

.aa-header__bar {
  display: block;
  width: 22px;
  height: 2px;
  background: #fafafa;
  border-radius: 2px;
}

.aa-header__mobile-menu {
  display: flex;
  flex-direction: column;
  padding: 1rem 2rem;
  background: #0a1322;
  border-top: 1px solid rgba(255, 255, 255, 0.08);
  gap: 0.75rem;
}

.aa-header__mobile-menu a {
  color: #fafafa;
  text-decoration: none;
  font-size: 1rem;
  padding: 0.5rem 0;
}

@media (max-width: 768px) {
  .aa-header__nav { display: none; }
  .aa-header__toggle { display: flex; }
}

@media (prefers-reduced-motion: reduce) {
  .aa-header,
  .aa-header__cta,
  .aa-header__link {
    transition: none !important;
    transform: none !important;
    animation: none !important;
  }
}

</file>
</tool_call>

