<file path="src/components/Hero.css">
.aa-hero {
  position: relative;
  min-height: 86vh;
  display: flex;
  align-items: center;
  background: #0a1322;
  overflow: hidden;
  padding: 5rem 2rem;
}

.aa-hero__inner {
  max-width: 1200px;
  margin: 0 auto;
  display: grid;
  grid-template-columns: 1.1fr 0.9fr;
  gap: 4rem;
  align-items: center;
  position: relative;
  z-index: 1;
}

.aa-hero__badge {
  display: inline-flex;
  align-items: center;
  gap: 0.5rem;
  padding: 0.35rem 1rem;
  background: rgba(56, 189, 248, 0.08);
  border: 1px solid rgba(56, 189, 248, 0.22);
  border-radius: 999px;
  color: #e4e4e7;
  font-size: 0.82rem;
  font-weight: 500;
  margin-bottom: 1.5rem;
}

.aa-hero__badge-pulse {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: #38bdf8;
  box-shadow: 0 0 8px #38bdf8;
}

.aa-hero__title {
  font-family: 'Plus Jakarta Sans', sans-serif;
  font-size: clamp(2.2rem, 4.5vw, 3.6rem);
  font-weight: 800;
  color: #fafafa;
  line-height: 1.14;
  letter-spacing: -0.02em;
  margin: 0 0 1.5rem;
}

.aa-hero__subtitle {
  font-size: 1.1rem;
  color: #a1a1aa;
  line-height: 1.7;
  margin: 0 0 2.2rem;
}

.aa-hero__actions {
  display: flex;
  gap: 1rem;
  flex-wrap: wrap;
}

.aa-hero__btn-primary {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 0.85rem 2rem;
  background: #38bdf8;
  color: #0c0d12;
  font-weight: 700;
  font-size: 0.95rem;
  text-decoration: none;
  border-radius: 8px;
  transition: all 0.2s ease;
}

.aa-hero__btn-primary:hover {
  background: #0284c7;
  transform: translateY(-2px);
  box-shadow: 0 8px 24px rgba(56, 189, 248, 0.35);
}

.aa-hero__btn-secondary {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 0.85rem 2rem;
  background: rgba(56, 189, 248, 0.04);
  color: #fafafa;
  border: 1px solid rgba(56, 189, 248, 0.32);
  font-weight: 600;
  font-size: 0.95rem;
  text-decoration: none;
  border-radius: 8px;
  transition: all 0.2s ease;
}

.aa-hero__btn-secondary:hover {
  border-color: #38bdf8;
  color: #38bdf8;
  transform: translateY(-2px);
}

.aa-hero__right {
  position: relative;
}

.aa-hero__backdrop {
  position: absolute;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
  width: 420px;
  height: 420px;
  border-radius: 50%;
  background: radial-gradient(circle, rgba(56, 189, 248, 0.24) 0%, transparent 70%);
  filter: blur(32px);
  pointer-events: none;
}

.aa-hero__card {
  position: relative;
  background: #132138;
  border: 1px solid rgba(255, 255, 255, 0.12);
  border-radius: 14px;
  padding: 2rem;
  box-shadow: 0 20px 48px rgba(0, 0, 0, 0.4);
}

.aa-hero__card-header {
  display: flex;
  align-items: center;
  gap: 0.4rem;
  margin-bottom: 1.5rem;
  padding-bottom: 1rem;
  border-bottom: 1px solid rgba(255, 255, 255, 0.08);
}

.aa-hero__card-dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: rgba(255, 255, 255, 0.2);
}

.aa-hero__card-status {
  margin-left: auto;
  font-size: 0.72rem;
  font-weight: 700;
  letter-spacing: 0.08em;
  color: #38bdf8;
}

.aa-hero__card-title {
  font-family: 'Plus Jakarta Sans', sans-serif;
  font-size: 1.35rem;
  font-weight: 700;
  color: #fafafa;
  margin: 0 0 0.75rem;
}

.aa-hero__card-desc {
  font-size: 0.95rem;
  color: #a1a1aa;
  line-height: 1.6;
  margin: 0 0 1.5rem;
}

.aa-hero__card-stat {
  display: flex;
  justify-content: space-between;
  align-items: center;
}

.aa-hero__card-tag {
  padding: 0.25rem 0.75rem;
  background: rgba(255, 255, 255, 0.06);
  border-radius: 6px;
  color: #38bdf8;
  font-size: 0.8rem;
  font-weight: 600;
}

.aa-hero__card-metric {
  color: #fafafa;
  font-size: 0.85rem;
  font-weight: 600;
}

@media (max-width: 900px) {
  .aa-hero__inner { grid-template-columns: 1fr; gap: 3rem; }
}

.aa-hero__left {
  animation: aaHeroLeftEnter 0.6s cubic-bezier(0.16, 1, 0.3, 1) 0ms both;
}

.aa-hero__right {
  animation: aaHeroRightEnter 0.6s cubic-bezier(0.16, 1, 0.3, 1) 160ms both;
}

@keyframes aaHeroLeftEnter {
  from { opacity: 0; transform: translateY(14px); }
  to { opacity: 1; transform: translateY(0); }
}

@keyframes aaHeroRightEnter {
  from { opacity: 0; transform: translateY(14px); }
  to { opacity: 1; transform: translateY(0); }
}

@media (prefers-reduced-motion: reduce) {
  .aa-hero__left,
  .aa-hero__right,
  .aa-hero__btn-primary,
  .aa-hero__btn-secondary {
    animation: none !important;
    transition: none !important;
    transform: none !important;
    opacity: 1 !important;
  }
}

</file>
</tool_call>

