import React from 'react';
import './AdvisoryCapabilities.css';

interface Item {
  title: string;
  tag: string;
  desc: string;
}

const ITEMS: Item[] = [
  {
    "title": "Fractional CFO & Runway Modeling",
    "tag": "Strategic",
    "desc": "Multi-scenario cash burn forecasting, capital allocation roadmaps, and investor board deck preparation."
  },
  {
    "title": "R&D Tax Credit Optimization",
    "tag": "Tax",
    "desc": "Maximizing federal and state research incentives to reclaim up to $250k annually against payroll taxes."
  },
  {
    "title": "Automated Cloud Accounting",
    "tag": "Operations",
    "desc": "Full QuickBooks and NetSuite migration with automated Stripe reconciliation and multi-currency ledgers."
  },
  {
    "title": "SOC 1 & GAAP Audit Prep",
    "tag": "Compliance",
    "desc": "Rigorous balance sheet substantiation, revenue recognition (ASC 606), and external auditor management."
  }
];

export function AdvisoryCapabilities() {
  return (
    <section className="aa-split" id="services" aria-labelledby="aa-split-title">
      <div className="aa-split__inner">
        <div className="aa-split__sticky">
          <p className="aa-split__eyebrow">Curated Solutions</p>
          <h2 id="aa-split-title" className="aa-split__title">
            Advisory Capabilities
          </h2>
          <p className="aa-split__desc">
            Strategic fractional CFO leadership, R&D tax credit monetization, and institutional audit preparation for venture-backed startups.
          </p>
          <div className="aa-split__badge">
            <span className="aa-split__badge-dot" aria-hidden="true" />
            <span>Active Availability</span>
          </div>
          <a href="mailto:partners@apexadvisorycfo.com" className="aa-split__cta">
            Contact Specialist
          </a>
        </div>

        <div className="aa-split__feed">
          {ITEMS.map((item, idx) => (
            <article key={item.title} className="aa-split__card">
              <div className="aa-split__card-top">
                <span className="aa-split__card-index">0{idx + 1}</span>
                <span className="aa-split__card-tag">{item.tag}</span>
              </div>
              <h3 className="aa-split__card-title">{item.title}</h3>
              <p className="aa-split__card-desc">{item.desc}</p>
              <div className="aa-split__card-check">
                <span className="aa-split__check-icon">&check;</span>
                <span>Verified Deliverable Specification</span>
              </div>
            </article>
          ))}
        </div>
      </div>
    </section>
  );
}

