import React, { useState, useEffect } from 'react';
import './Header.css';

export function Header() {
  const [scrolled, setScrolled] = useState(false);
  const [menuOpen, setMenuOpen] = useState(false);

  useEffect(() => {
    const onScroll = () => setScrolled(window.scrollY > 15);
    window.addEventListener('scroll', onScroll, { passive: true });
    return () => window.removeEventListener('scroll', onScroll);
  }, []);

  return (
    <header className={`ns-header${scrolled ? ' ns-header--scrolled' : ''}`} role="banner">
      <div className="ns-header__inner">
        <a href="#" className="ns-header__logo" aria-label="Nova Strike Studios Home">
          Nova Strike Studios
        </a>

        <nav className="ns-header__nav" aria-label="Main Navigation">
          <a href="#hero" className="ns-header__link">Home</a>
          <a href="#titles" className="ns-header__link">Active Games</a>
          <a href="#footer" className="ns-header__link">Contact</a>
        </nav>

        <div className="ns-header__actions">
          <a href="mailto:community@novastrikestudios.com" className="ns-header__cta">
            Wishlist on Steam
          </a>
          <button
            type="button"
            className="ns-header__toggle"
            aria-label="Toggle navigation menu"
            aria-expanded={menuOpen}
            onClick={() => setMenuOpen(!menuOpen)}
          >
            <span className="ns-header__bar" />
            <span className="ns-header__bar" />
            <span className="ns-header__bar" />
          </button>
        </div>
      </div>

      {menuOpen && (
        <div className="ns-header__mobile-menu">
          <a href="#hero" onClick={() => setMenuOpen(false)}>Home</a>
          <a href="#titles" onClick={() => setMenuOpen(false)}>Active Games</a>
          <a href="#footer" onClick={() => setMenuOpen(false)}>Contact</a>
        </div>
      )}
    </header>
  );
}

