import React, { useState, useEffect } from 'react';
import './Header.css';

export function Header() {
  const [scrolled, setScrolled] = useState(false);
  const [menuOpen, setMenuOpen] = useState(false);

  useEffect(() => {
    const onScroll = () => setScrolled(window.scrollY > 15);
    window.addEventListener('scroll', onScroll, { passive: true });
    return () => window.removeEventListener('scroll', onScroll);
  }, []);

  return (
    <header className={`zv-header${scrolled ? ' zv-header--scrolled' : ''}`} role="banner">
      <div className="zv-header__inner">
        <a href="#" className="zv-header__logo" aria-label="Zenith Institutional Vault Home">
          Zenith Institutional Vault
        </a>

        <nav className="zv-header__nav" aria-label="Main Navigation">
          <a href="#hero" className="zv-header__link">Home</a>
          <a href="#security" className="zv-header__link">Security Architecture</a>
          <a href="#footer" className="zv-header__link">Contact</a>
        </nav>

        <div className="zv-header__actions">
          <a href="mailto:institutional@zenithvault.com" className="zv-header__cta">
            Open Custody Account
          </a>
          <button
            type="button"
            className="zv-header__toggle"
            aria-label="Toggle navigation menu"
            aria-expanded={menuOpen}
            onClick={() => setMenuOpen(!menuOpen)}
          >
            <span className="zv-header__bar" />
            <span className="zv-header__bar" />
            <span className="zv-header__bar" />
          </button>
        </div>
      </div>

      {menuOpen && (
        <div className="zv-header__mobile-menu">
          <a href="#hero" onClick={() => setMenuOpen(false)}>Home</a>
          <a href="#security" onClick={() => setMenuOpen(false)}>Security Architecture</a>
          <a href="#footer" onClick={() => setMenuOpen(false)}>Contact</a>
        </div>
      )}
