import React, { useState, useEffect } from 'react';
import './Header.css';

export function Header() {
  const [scrolled, setScrolled] = useState(false);
  const [menuOpen, setMenuOpen] = useState(false);

  useEffect(() => {
    const onScroll = () => setScrolled(window.scrollY > 15);
    window.addEventListener('scroll', onScroll, { passive: true });
    return () => window.removeEventListener('scroll', onScroll);
  }, []);

  return (
    <header className={`sp-header${scrolled ? ' sp-header--scrolled' : ''}`} role="banner">
      <div className="sp-header__inner">
        <a href="#" className="sp-header__logo" aria-label="Sentinel Protective Services Home">
          Sentinel Protective Services
        </a>

        <nav className="sp-header__nav" aria-label="Main Navigation">
          <a href="#hero" className="sp-header__link">Home</a>
          <a href="#tiers" className="sp-header__link">Protection Tiers</a>
          <a href="#footer" className="sp-header__link">Contact</a>
        </nav>

        <div className="sp-header__actions">
          <a href="mailto:operations@sentinelprotectiveservices.com" className="sp-header__cta">
            Request Security Assessment
          </a>
          <button
            type="button"
            className="sp-header__toggle"
            aria-label="Toggle navigation menu"
            aria-expanded={menuOpen}
            onClick={() => setMenuOpen(!menuOpen)}
          >
            <span className="sp-header__bar" />
            <span className="sp-header__bar" />
            <span className="sp-header__bar" />
          </button>
        </div>
      </div>

      {menuOpen && (
        <div className="sp-header__mobile-menu">
          <a href="#hero" onClick={() => setMenuOpen(false)}>Home</a>
          <a href="#tiers" onClick={() => setMenuOpen(false)}>Protection Tiers</a>
          <a href="#footer" onClick={() => setMenuOpen(false)}>Contact</a>
        </div>
      )}
    </header>
  );
}

