import React, { useState, useEffect } from 'react';
import './Header.css';

export function Header() {
  const [scrolled, setScrolled] = useState(false);
  const [menuOpen, setMenuOpen] = useState(false);

  useEffect(() => {
    const onScroll = () => setScrolled(window.scrollY > 15);
    window.addEventListener('scroll', onScroll, { passive: true });
    return () => window.removeEventListener('scroll', onScroll);
  }, []);

  return (
    <header className={`si-header${scrolled ? ' si-header--scrolled' : ''}`} role="banner">
      <div className="si-header__inner">
        <a href="#" className="si-header__logo" aria-label="Sacred Ink Tattoo Studio Home">
          Sacred Ink Tattoo Studio
        </a>

        <nav className="si-header__nav" aria-label="Main Navigation">
          <a href="#hero" className="si-header__link">Home</a>
          <a href="#artists" className="si-header__link">Resident Artists</a>
          <a href="#footer" className="si-header__link">Contact</a>
        </nav>

        <div className="si-header__actions">
          <a href="mailto:booking@sacredinktattoo.com" className="si-header__cta">
            Submit Tattoo Inquiry
          </a>
          <button
            type="button"
            className="si-header__toggle"
            aria-label="Toggle navigation menu"
            aria-expanded={menuOpen}
            onClick={() => setMenuOpen(!menuOpen)}
          >
            <span className="si-header__bar" />
            <span className="si-header__bar" />
            <span className="si-header__bar" />
          </button>
        </div>
      </div>

      {menuOpen && (
        <div className="si-header__mobile-menu">
          <a href="#hero" onClick={() => setMenuOpen(false)}>Home</a>
          <a href="#artists" onClick={() => setMenuOpen(false)}>Resident Artists</a>
          <a href="#footer" onClick={() => setMenuOpen(false)}>Contact</a>
        </div>
      )}
    </header>
  );
}

