import React, { useState, useEffect } from 'react';
import './Header.css';

export function Header() {
  const [scrolled, setScrolled] = useState(false);
  const [menuOpen, setMenuOpen] = useState(false);

  useEffect(() => {
    const onScroll = () => setScrolled(window.scrollY > 15);
    window.addEventListener('scroll', onScroll, { passive: true });
    return () => window.removeEventListener('scroll', onScroll);
  }, []);

  return (
    <header className={`vh-header${scrolled ? ' vh-header--scrolled' : ''}`} role="banner">
      <div className="vh-header__inner">
        <a href="#" className="vh-header__logo" aria-label="Vanguard Horology Atelier Home">
          Vanguard Horology Atelier
        </a>

        <nav className="vh-header__nav" aria-label="Main Navigation">
          <a href="#hero" className="vh-header__link">Home</a>
          <a href="#vault" className="vh-header__link">Vault Highlights</a>
          <a href="#footer" className="vh-header__link">Contact</a>
        </nav>

        <div className="vh-header__actions">
          <a href="mailto:timepieces@vanguardhorology.com" className="vh-header__cta">
            View Private Vault
          </a>
          <button
            type="button"
            className="vh-header__toggle"
            aria-label="Toggle navigation menu"
            aria-expanded={menuOpen}
            onClick={() => setMenuOpen(!menuOpen)}
          >
            <span className="vh-header__bar" />
            <span className="vh-header__bar" />
            <span className="vh-header__bar" />
          </button>
        </div>
      </div>

      {menuOpen && (
        <div className="vh-header__mobile-menu">
          <a href="#hero" onClick={() => setMenuOpen(false)}>Home</a>
          <a href="#vault" onClick={() => setMenuOpen(false)}>Vault Highlights</a>
          <a href="#footer" onClick={() => setMenuOpen(false)}>Contact</a>
        </div>
      )}
    </header>
  );
}

