import React, { useState, useEffect } from 'react';
import './Header.css';

export function Header() {
  const [scrolled, setScrolled] = useState(false);
  const [menuOpen, setMenuOpen] = useState(false);

  useEffect(() => {
    const onScroll = () => setScrolled(window.scrollY > 15);
    window.addEventListener('scroll', onScroll, { passive: true });
    return () => window.removeEventListener('scroll', onScroll);
  }, []);

  return (
    <header className={`ca-header${scrolled ? ' ca-header--scrolled' : ''}`} role="banner">
      <div className="ca-header__inner">
        <a href="#" className="ca-header__logo" aria-label="Chalet Alpen Solitude Home">
          Chalet Alpen Solitude
        </a>

        <nav className="ca-header__nav" aria-label="Main Navigation">
          <a href="#hero" className="ca-header__link">Home</a>
          <a href="#amenities" className="ca-header__link">Chalet Amenities</a>
          <a href="#footer" className="ca-header__link">Contact</a>
        </nav>

        <div className="ca-header__actions">
          <a href="mailto:concierge@alpensolitude.ch" className="ca-header__cta">
            Reserve Chalet
          </a>
          <button
            type="button"
            className="ca-header__toggle"
            aria-label="Toggle navigation menu"
            aria-expanded={menuOpen}
            onClick={() => setMenuOpen(!menuOpen)}
          >
            <span className="ca-header__bar" />
            <span className="ca-header__bar" />
            <span className="ca-header__bar" />
          </button>
        </div>
      </div>

      {menuOpen && (
        <div className="ca-header__mobile-menu">
          <a href="#hero" onClick={() => setMenuOpen(false)}>Home</a>
          <a href="#amenities" onClick={() => setMenuOpen(false)}>Chalet Amenities</a>
          <a href="#footer" onClick={() => setMenuOpen(false)}>Contact</a>
        </div>
      )}
    </header>
  );
}

