import React, { useState, useEffect } from 'react';
import './Header.css';

export function Header() {
  const [scrolled, setScrolled] = useState(false);
  const [menuOpen, setMenuOpen] = useState(false);

  useEffect(() => {
    const onScroll = () => setScrolled(window.scrollY > 15);
    window.addEventListener('scroll', onScroll, { passive: true });
    return () => window.removeEventListener('scroll', onScroll);
  }, []);

  return (
    <header className={`tv-header${scrolled ? ' tv-header--scrolled' : ''}`} role="banner">
      <div className="tv-header__inner">
        <a href="#" className="tv-header__logo" aria-label="TerraVolt Microgrids Home">
          TerraVolt Microgrids
        </a>

        <nav className="tv-header__nav" aria-label="Main Navigation">
          <a href="#hero" className="tv-header__link">Home</a>
          <a href="#architecture" className="tv-header__link">System Architecture</a>
          <a href="#footer" className="tv-header__link">Contact</a>
        </nav>

        <div className="tv-header__actions">
          <a href="mailto:grids@terravoltenergy.com" className="tv-header__cta">
            Request Feasibility Study
          </a>
          <button
            type="button"
            className="tv-header__toggle"
            aria-label="Toggle navigation menu"
            aria-expanded={menuOpen}
            onClick={() => setMenuOpen(!menuOpen)}
          >
            <span className="tv-header__bar" />
            <span className="tv-header__bar" />
            <span className="tv-header__bar" />
          </button>
        </div>
      </div>

      {menuOpen && (
        <div className="tv-header__mobile-menu">
          <a href="#hero" onClick={() => setMenuOpen(false)}>Home</a>
          <a href="#architecture" onClick={() => setMenuOpen(false)}>System Architecture</a>
          <a href="#footer" onClick={() => setMenuOpen(false)}>Contact</a>
