.hsc-bento__card--hero {
  grid-column: span 2;
  grid-row: span 2;
  background: linear-gradient(135deg, rgba(255, 255, 255, 0.05) 0%, rgba(255, 255, 255, 0.02) 100%);
}

.hsc-bento__card--metric {
  grid-column: span 1;
  grid-row: span 2;
  justify-content: space-between;
}

.hsc-bento__card--standard {
  grid-column: span 1;
  grid-row: span 1;
}

