  letter-spacing: 0.08em;
  padding: 0.25rem 0.65rem;
  background: var(--color-iridescent-fade, var(--accent-color, #2dd4bf));
  color: var(--color-paper, #ffffff);
  border-radius: var(--radius-buttons, 16px);
}

.hsc-bento__tag {
  font-size: 0.78rem;
  color: var(--color-ash-mist, rgba(255, 255, 255, 0.6));
  font-family: monospace;
}

.hsc-bento__card-title {
  font-family: var(--font-heading, 'Space Grotesk', sans-serif);
  font-size: 1.25rem;
  font-weight: 700;
  color: var(--color-paper, #ffffff);
  margin-bottom: 0.75rem;
}

.hsc-bento__card-title--hero {
  font-size: 1.65rem;
}

.hsc-bento__card-desc {
  font-family: var(--font-body, 'Inter', sans-serif);
