}

.pcv-bento__grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  grid-auto-rows: minmax(210px, auto);
  gap: 1.5rem;
}

.pcv-bento__card {
  position: relative;
  background: rgba(255, 255, 255, 0.03);
