  font-family: var(--font-heading, 'Space Grotesk', sans-serif);
  font-size: 1.25rem;
  font-weight: 700;
  color: var(--color-paper, #ffffff);
  margin-bottom: 0.75rem;
}

.pcv-bento__card-title--hero {
  font-size: 1.65rem;
}

.pcv-bento__card-desc {
