  color: var(--color-ash-mist, #94a3b8);
  white-space: pre-wrap;
}

.pcv-bento__card-action {
  margin-top: auto;
}

.pcv-bento__link {
  color: var(--color-iridescent-fade, var(--accent-color, #b32aea));
  font-size: 0.875rem;
  font-weight: 600;
  text-decoration: none;
