import React, { useState, useEffect } from 'react';
import './Header.css';

export function Header() {
  const [scrolled, setScrolled] = useState(false);
  const [menuOpen, setMenuOpen] = useState(false);

  useEffect(() => {
    const onScroll = () => setScrolled(window.scrollY > 15);
    window.addEventListener('scroll', onScroll, { passive: true });
    return () => window.removeEventListener('scroll', onScroll);
  }, []);

  return (
    <header className={`rgh-header${scrolled ? ' rgh-header--scrolled' : ''}`} role="banner">
      <div className="rgh-header__inner">
        <a href="#" className="rgh-header__logo" aria-label="Raw Goods Heavyweight Home">
          Raw Goods Heavyweight
        </a>

        <nav className="rgh-header__nav" aria-label="Main Navigation">
          <a href="#hero" className="rgh-header__link">Home</a>
          <a href="#denim_pieces" className="rgh-header__link">Heavy Iron Collection</a>
          <a href="#footer" className="rgh-header__link">Contact</a>
        </nav>

        <div className="rgh-header__actions">
          <a href="mailto:workshop@rawgoods.jp" className="rgh-header__cta">
            View Denim Drops
          </a>
          <button
            type="button"
            className="rgh-header__toggle"
            aria-label="Toggle navigation menu"
            aria-expanded={menuOpen}
            onClick={() => setMenuOpen(!menuOpen)}
          >
            <span className="rgh-header__bar" />
            <span className="rgh-header__bar" />
            <span className="rgh-header__bar" />
          </button>
        </div>
      </div>

      {menuOpen && (
        <div className="rgh-header__mobile-menu" role="dialog" aria-modal="true">
          <a href="#hero" className="rgh-header__mobile-link" onClick={() => setMenuOpen(false)}>Home</a>
          <a href="#denim_pieces" className="rgh-header__mobile-link" onClick={() => setMenuOpen(false)}>Heavy Iron Collection</a>
          <a href="#footer" className="rgh-header__mobile-link" onClick={() => setMenuOpen(false)}>Contact</a>
          <a href="mailto:workshop@rawgoods.jp" className="rgh-header__mobile-cta" onClick={() => setMenuOpen(false)}>View Denim Drops</a>
        </div>
      )}
    </header>
  );
}
