                <p className="ler-editorial__chapter-desc">{ch.desc}</p>
                <a href="#contact" className="ler-editorial__chapter-link">
                  Read Monograph &rarr;
                </a>
              </article>
            ))}
          </div>
        </div>
      </div>
    </section>
  );
}
