import React, { useState, useEffect } from 'react';
import './Header.css';

export function Header() {
  const [scrolled, setScrolled] = useState(false);
  const [menuOpen, setMenuOpen] = useState(false);

  useEffect(() => {
    const onScroll = () => setScrolled(window.scrollY > 15);
    window.addEventListener('scroll', onScroll, { passive: true });
    return () => window.removeEventListener('scroll', onScroll);
  }, []);

  return (
    <header className={`rd-header${scrolled ? ' rd-header--scrolled' : ''}`} role="banner">
      <div className="rd-header__inner">
        <a href="#" className="rd-header__logo" aria-label="Resolve Desk Home">
          Resolve Desk
        </a>

        <nav className="rd-header__nav" aria-label="Main Navigation">
          <a href="#hero" className="rd-header__link">Home</a>
          <a href="#support_features" className="rd-header__link">Support Features</a>
          <a href="#footer" className="rd-header__link">Contact</a>
        </nav>

        <div className="rd-header__actions">
          <a href="mailto:success@resolvedesk.io" className="rd-header__cta">
            Start 30-Day Trial
          </a>
          <button
            type="button"
            className="rd-header__toggle"
            aria-label="Toggle navigation menu"
            aria-expanded={menuOpen}
            onClick={() => setMenuOpen(!menuOpen)}
          >
            <span className="rd-header__bar" />
            <span className="rd-header__bar" />
            <span className="rd-header__bar" />
          </button>
        </div>
      </div>

      {menuOpen && (
        <div className="rd-header__mobile-menu" role="dialog" aria-modal="true">
          <a href="#hero" className="rd-header__mobile-link" onClick={() => setMenuOpen(false)}>Home</a>
          <a href="#support_features" className="rd-header__mobile-link" onClick={() => setMenuOpen(false)}>Support Features</a>
          <a href="#footer" className="rd-header__mobile-link" onClick={() => setMenuOpen(false)}>Contact</a>
          <a href="mailto:success@resolvedesk.io" className="rd-header__mobile-cta" onClick={() => setMenuOpen(false)}>Start 30-Day Trial</a>
        </div>
      )}
    </header>
  );
}
