import React, { useState } from 'react';
import './SupportFeatures.css';

interface Feature {
  id: string;
  category: string;
  title: string;
  desc: string;
  badge: string;
}

interface Review {
  id: string;
  quote: string;
  author: string;
  role: string;
  rating: number;
}

const FEATURES: Feature[] = [{'title': 'AI First-Response Deflection', 'tag': 'Knowledge Base', 'desc': 'Resolves common questions about billing, refunds, and password resets in under 10 seconds.'}, {'title': 'SLA Priority Countdown', 'tag': 'Tiered Routing', 'desc': 'Color-coded timers warn support agents 15 minutes before an enterprise contract SLA breaches.'}, {'title': 'Live Co-Browsing & Session Replay', 'tag': 'Instant Context', 'desc': 'Inspect user browser console errors and network failures directly alongside the ticket thread.'}, {'title': 'Automated CSAT Surveys', 'tag': 'Net Promoter', 'desc': 'Trigger one-click satisfaction ratings upon ticket closure and track agent performance metrics.'}];
const REVIEWS: Review[] = [{'id': '1', 'quote': 'Deploying Resolve Desk transformed our delivery velocity. The ai first-response deflection capabilities delivered immediate impact.', 'author': 'Alex Chen', 'role': 'Head of Engineering, Resolve Desk', 'rating': 5}, {'id': '2', 'quote': 'With Resolve Desk, we automated omnichannel support with ai ticket deflection & sla breach warnings while accelerating our product delivery.', 'author': 'Samantha Wei', 'role': 'VP of Technology at Resolve Desk Group', 'rating': 5}, {'id': '3', 'quote': 'Our developers love using Resolve Desk. The sla priority countdown workflow is best in class.', 'author': 'Marcus Thorne', 'role': 'Principal Architect', 'rating': 5}];
const CATEGORIES: { id: string; label: string }[] = [{'id': 'all', 'label': 'All Capabilities'}, {'id': 'core', 'label': 'Core Engine'}, {'id': 'security', 'label': 'Security & Auth'}, {'id': 'scale', 'label': 'Scale & Telemetry'}];

export function SupportFeatures() {
  const [activeTab, setActiveTab] = useState<string>('all');
  const [activeSlide, setActiveSlide] = useState<number>(0);

  const filteredFeatures = activeTab === 'all'
    ? FEATURES
    : FEATURES.filter((f) => f.category === activeTab);

  const prevSlide = () => {
    setActiveSlide((prev) => (prev - 1 + REVIEWS.length) % REVIEWS.length);
  };

  const nextSlide = () => {
    setActiveSlide((prev) => (prev + 1) % REVIEWS.length);
  };

  const currentReview = REVIEWS[activeSlide];

  return (
    <section className="rd-tabs" id="supportfeatures" aria-labelledby="rd-tabs-title">
      <div className="rd-tabs__inner">
        {/* 1. Header & Tab Navigation */}
        <div className="rd-tabs__header">
          <p className="rd-tabs__eyebrow">SAAS SOLUTIONS</p>
          <h2 id="rd-tabs-title" className="rd-tabs__title">
            Support Features
          </h2>
          <p className="rd-tabs__subtitle">
            Explore verified solutions and live client outcomes from Resolve Desk.
          </p>

          <div className="rd-tabs__nav" role="tablist" aria-label="Feature categories">
            {CATEGORIES.map((cat) => (
              <button
                key={cat.id}
                type="button"
                role="tab"
                aria-selected={activeTab === cat.id}
                className={`rd-tabs__tab${activeTab === cat.id ? ' is-active' : ''}`}
                onClick={() => setActiveTab(cat.id)}
              >
                {cat.label}
              </button>
            ))}
          </div>
        </div>

        {/* 2. Filtered Cards Grid */}
        <div className="rd-tabs__grid">
          {filteredFeatures.map((item) => (
            <div key={item.id} className="rd-tabs__card">
              <div className="rd-tabs__card-top">
                <span className="rd-tabs__badge">{item.badge}</span>
                <span className="rd-tabs__category">{item.category}</span>
              </div>
              <h3 className="rd-tabs__card-title">{item.title}</h3>
              <p className="rd-tabs__card-desc">{item.desc}</p>
            </div>
          ))}
        </div>

        {/* 3. Carousel Component — Testimonials & Proof */}
        <div className="rd-tabs__carousel" aria-label="Customer Testimonials">
          <div className="rd-tabs__carousel-box">
            <div className="rd-tabs__stars" aria-label="5 stars rating">
              {'★'.repeat(currentReview.rating)}
            </div>

            <blockquote className="rd-tabs__quote">
              &ldquo;{currentReview.quote}&rdquo;
            </blockquote>

            <div className="rd-tabs__author">
              <div className="rd-tabs__author-avatar" aria-hidden="true">
                {currentReview.author.split(' ').map((n) => n[0]).join('')}
              </div>
              <div>
                <h4 className="rd-tabs__author-name">{currentReview.author}</h4>
                <span className="rd-tabs__author-role">{currentReview.role}</span>
              </div>
            </div>

            <div className="rd-tabs__carousel-controls">
              <button
                type="button"
                onClick={prevSlide}
                className="rd-tabs__carousel-btn"
                aria-label="Previous testimonial"
              >
                &larr;
              </button>
              <span className="rd-tabs__carousel-counter">
                0{activeSlide + 1} / 0{REVIEWS.length}
              </span>
              <button
                type="button"
                onClick={nextSlide}
                className="rd-tabs__carousel-btn"
                aria-label="Next testimonial"
              >
                &rarr;
              </button>
            </div>
          </div>
        </div>
      </div>
    </section>
  );
}
